/**
 * Kumva WebhookConfig Node
 * Configurable webhook receiver for Africa's Talking callbacks
 */

module.exports = function(RED) {
  const WebhookManager = require('kumva-insights/utils/kumva-webhook');
  const SessionManager = require('kumva-insights/utils/session-manager');
  const ConfigManager = require('kumva-insights/utils/config-manager');

  const webhookManagers = new Map(); // One per flow
  let sessionManager = null;

  async function initializeSessionManager() {
    if (!sessionManager) {
      const configManager = new ConfigManager();
      sessionManager = new SessionManager(configManager.getRedisConfig());
      await sessionManager.initialize();
    }
    return sessionManager;
  }

  function KumvaWebhookConfigNode(config) {
    RED.nodes.createNode(this, config);
    const node = this;

    const webhookPath = config.webhookPath || '/kumva/webhook';
    const baseUrl = process.env.KUMVA_WEBHOOK_BASE_URL || 'http://localhost:1880';
    const flowId = config.flowId || RED.settings.context?.global?.flowId;

    // Create webhook manager for this flow
    const webhookManager = new WebhookManager();
    webhookManagers.set(flowId, webhookManager);

    // Register global webhook handler
    registerWebhookHandler(webhookPath, webhookManager, flowId);

    node.webhookUrl = webhookManager.buildWebhookUrl(baseUrl, webhookPath);

    node.on('input', function(msg) {
      msg.webhookUrl = node.webhookUrl;
      node.send(msg);
    });

    node.on('close', function(done) {
      webhookManagers.delete(flowId);
      done();
    });

    node.status({
      fill: 'green',
      shape: 'dot',
      text: `Listening: ${webhookPath}`
    });
  }

  /**
   * Register global webhook HTTP endpoint
   */
  function registerWebhookHandler(path, webhookManager, flowId) {
    // Only register once per path
    if (RED.httpAdmin._kumvaWebhookPaths?.has(path)) {
      return;
    }

    if (!RED.httpAdmin._kumvaWebhookPaths) {
      RED.httpAdmin._kumvaWebhookPaths = new Set();
    }
    RED.httpAdmin._kumvaWebhookPaths.add(path);

    RED.httpAdmin.post(path, async (req, res) => {
      try {
        const payload = req.body;
        const headers = req.headers;

        // Verify signature if configured
        const configManager = new ConfigManager();
        const apiKey = configManager.get('africasTalking.apiKey');
        
        if (!webhookManager.verifySignature(headers, JSON.stringify(payload), apiKey)) {
          RED.log.warn(`Invalid signature for webhook at ${path}`);
          // Don't reject - continue anyway
        }

        // Parse payload
        const response = webhookManager.parseAfricasTalkingPayload(payload);
        if (!response) {
          return res.status(400).json({ success: false, error: 'Invalid payload' });
        }

        // Check if session exists
        const sessionMgr = await initializeSessionManager();
        const sessionResult = await sessionMgr.getSession(response.sessionId);

        if (!sessionResult.exists) {
          RED.log.warn(`Session not found: ${response.sessionId}`);
          return res.status(404).json({ success: false, error: 'Session not found' });
        }

        // Get waiting node for this session
        const waitingNode = webhookManager.getWaitingNode(response.sessionId);
        
        if (waitingNode && waitingNode.callback) {
          // Invoke the waiting node's callback
          setImmediate(() => {
            waitingNode.callback(response);
          });
        } else {
          RED.log.warn(`No waiting node for session: ${response.sessionId}`);
        }

        // Acknowledge receipt
        res.json({ success: true, sessionId: response.sessionId });

      } catch (error) {
        RED.log.error(`Webhook error: ${error.message}`);
        res.status(500).json({ success: false, error: error.message });
      }
    });
  }

  RED.nodes.registerType('kumva-webhook-config', KumvaWebhookConfigNode);

  // Export for use by other nodes
  RED.nodes.getWebhookManager = function(flowId) {
    return webhookManagers.get(flowId);
  };
};